namespace ghidra.app.util.disassemble;





using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using generic.theme;
using generic.theme.GThemeDefaults.Colors;
using ghidra.app.util;
using ghidra.app.util.viewer.field;
using ghidra.app.util.viewer.format;
using ghidra.app.util.viewer.proxy;
using ghidra.framework.options;
using ghidra.framework.options;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util.classfinder;

public class ExternalDisassemblyFieldFactory : FieldFactory {
	public static readonly GColor COLOR = new GColor("color.fg.listing.disassembly.external");

	private static List<ExternalDisassembler> availableDisassemblers;

	private static List<ExternalDisassembler> getAvailableDisassemblers() {
		if (availableDisassemblers != null) {
			return availableDisassemblers;
		}
		availableDisassemblers = new();

		// find the available external disassemblers
		List<ExternalDisassembler> extDisassemblers =
			ClassSearcher.getInstances(typeof(ExternalDisassembler));

		foreach (ExternalDisassembler disassember in extDisassemblers) {
			availableDisassemblers.add(disassember);
		}
		return availableDisassemblers;
	}

	public static readonly string FIELD_NAME = "External Disassembly";

	public ExternalDisassemblyFieldFactory() : base(FIELD_NAME)
    {
	}

	private ExternalDisassemblyFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {
	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		return (category == FieldFormatModel.INSTRUCTION_OR_DATA);
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation loc) {
		if (loc is ExternalDisassemblyFieldLocation) {
			return new FieldLocation(index, fieldNum,
				((ExternalDisassemblyFieldLocation) loc).getRow(),
				((ExternalDisassemblyFieldLocation) loc).getCharOffset());
		}
		return null;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		ProxyObj<object> proxy = bf.getProxy();
		object obj = proxy.getObject();
		if (!(obj is CodeUnit)) {
			return null;
		}
		CodeUnit cu = (CodeUnit) obj;

		return new ExternalDisassemblyFieldLocation(cu.getProgram(), cu.getMinAddress(), row, col);
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel,
			ListingHighlightProvider highlightProvider, ToolOptions options, ToolOptions fieldOptions) {
		return new ExternalDisassemblyFieldFactory(formatModel, highlightProvider, options,
			fieldOptions);
	}

	private ExternalDisassembler getDisassembler(Language language) {
		foreach (ExternalDisassembler disassembler in getAvailableDisassemblers()) {
			if (disassembler.isSupportedLanguage(language)) {
				return disassembler;
			}
		}
		return null;
	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		if (!enabled) {
			return null;
		}
		object obj = proxy.getObject();
		if (!(obj is CodeUnit)) {
			return null;
		}
		CodeUnit cu = (CodeUnit) obj;

		try {
			string disassembly = getDisassemblyText(cu);
			if (disassembly == null) {
				return null;
			}
			AttributedString text = new AttributedString(disassembly, COLOR, getMetrics());
			FieldElement fieldElement = new TextFieldElement(text, 0, 0);
			return ListingTextField.createSingleLineTextField(this, proxy, fieldElement,
				startX + varWidth, width, hlProvider);
		}
		catch (Exception e) {
			return getErrorText(proxy, varWidth, e);
		}
	}

	private string getDisassemblyText(CodeUnit cu)
    {
		Language language = cu.getProgram().getLanguage();
		ExternalDisassembler disassembler = getDisassembler(language);
		if (disassembler == null) {
			return null;
		}
		string disassembly = disassembler.getDisassembly(cu);
		if (disassembly == null) {
			return null;
		}
		string prefix = disassembler.getDisassemblyDisplayPrefix(cu);
		if (prefix != null) {
			disassembly = prefix + " " + disassembly;
		}
		return disassembly;
	}

	private ListingTextField getErrorText(ProxyObj<object> proxy, int varWidth, Exception e) {
		string message = e.getMessage();
		if (message == null) {
			message = e.toString();
		}
		AttributedString errorText = new AttributedString(message, Messages.ERROR, getMetrics());
		FieldElement fieldElement = new TextFieldElement(errorText, 0, 0);
		return ListingTextField.createSingleLineTextField(this, proxy, fieldElement,
			startX + varWidth, width, hlProvider);
	}
}
